DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PGlateximage.pl",
  "contextFraction.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

Context("Fraction");
$a=Fraction(random(-33,-13,4),4);
@decoys = (Real($a), int(Real($a)/2), Real(-$a-2), -Real($a), );
$xmin = -max(int(Real($a)*1.6), 10);
$xmax = -$xmin;

$image_1 = createLaTeXImage();
$image_1->addToPreamble(latexImagePreamble());
$image_1->BEGIN_LATEX_IMAGE
\begin{tikzpicture}
  \begin{axis}
    [
      numberline,
      xmin=$xmin,
      xmax=$xmax,
      xlabel={\(x\)},
      width=\orccaprintwidth
    ]
      \node[pin=90:{\(A\)}] at (axis cs:$decoys[0],0) {};
      \node[pin=90:{\(B\)}] at (axis cs:$decoys[1],0) {};
      \node[pin=90:{\(C\)}] at (axis cs:$decoys[2],0) {};
      \node[pin=90:{\(D\)}] at (axis cs:$decoys[3],0) {};
  \end{axis}
\end{tikzpicture}

END_LATEX_IMAGE

######
# Body
######

BEGIN_PGML
Which letter is [`[$a]`] on the number line?

>> [@image(insertGraph($image_1), width=>600)@]*  <<

[_]{$popup}{5}

END_PGML

#############
# End Problem
#############

ENDDOCUMENT();
